<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Commercial\Sponsors;
$sponsors = new Sponsors($db,$core->migrator(),$core->get('public_catalog'));
wp_set_current_user($admin); $initial=$sponsors->snapshot(); $entryId=0;
$payload=Sponsors::blank(); $payload['name']='Synthetic QA sponsor';$payload['url']='https://example.com/phase13-test';$payload['review_note']='Synthetic local QA review; not a real endorsement.';
$payload['translations']=['en_US'=>['title'=>'QA Sponsored resource','description'=>'Synthetic local QA sponsor description.'],'zh_CN'=>['title'=>'QA 赞助资源','description'=>'仅用于隔离测试的赞助说明。']];
$subscriber=p13_user('sponsor-subscriber');$manager=p13_user('sponsor-manager');get_userdata($manager)->add_cap(Sponsors::CAPABILITY);
p13_case('sponsors_disabled_configuration_has_no_public_records',function()use($sponsors,$initial,$admin){wp_set_current_user($admin);p13_assert($initial['enabled']===false,'Public sponsor display begins disabled');if($initial['revision']===0){p13_assert($initial===Sponsors::defaults(),'No unsolicited sponsor setting or default entries');}p13_assert($sponsors->forPlacement('home_after_search','zh_CN')===[]&&$sponsors->forPlacement('skill_detail_footer','en_US')===[],'Both placements empty by default');});
p13_case('sponsors_native_caps_draft_confirmation_cas_and_audit',function()use($sponsors,$payload,$subscriber,$manager,$admin,&$entryId){wp_set_current_user($subscriber);p13_reject(fn()=>$sponsors->snapshot(),'Subscriber cannot read sponsor control');p13_reject(fn()=>$sponsors->saveEntry(0,0,$payload,false),'Subscriber cannot save sponsor');wp_set_current_user($manager);$s=$sponsors->snapshot();$s=$sponsors->saveEntry(0,$s['revision'],$payload,false);$entryId=$s['entries'][array_key_last($s['entries'])]['id'];p13_assert($sponsors->publicEntry($entryId,'en_US')===null,'Draft stays private even after save');$d=$payload;$d['status']='enabled';$d['starts_at']=gmdate('Y-m-d H:i:s',time()-30);$d['ends_at']=gmdate('Y-m-d H:i:s',time()+3600);p13_reject(fn()=>$sponsors->saveEntry($entryId,$s['revision'],$d,false),'Explicit review required');$before=$sponsors->snapshot();p13_assert($before===$s,'Rejected approval atomic');$s=$sponsors->saveEntry($entryId,$s['revision'],$d,true);p13_assert($sponsors->publicEntry($entryId,'en_US')===null,'Individual approval does not enable global display');$s=$sponsors->setEnabled(true,$s['revision']);p13_reject(fn()=>$sponsors->setEnabled(false,$s['revision']-1),'Stale writer rejected');p13_assert($sponsors->publicEntry($entryId,'zh_CN')['title']==='QA 赞助资源','Live reviewed Chinese projection');$r=$sponsors->publicEntry($entryId,'en_US');foreach(['review_note','reviewed_by','reviewed_at','image_evidence']as$key)p13_assert(!array_key_exists($key,$r),'Private moderation field excluded '.$key);p13_assert(count($sponsors->history())>=3,'Draft approval/global events recorded');wp_set_current_user($admin);});
p13_case('sponsor_url_and_image_validation_no_fetch_or_execution',function()use($sponsors,$payload,$admin,$db,&$entryId){wp_set_current_user($admin);foreach(['http://example.com','javascript:alert(1)','https://127.0.0.1/','https://localhost/','https://example.com:443/','https://name:secret@example.com/','https://example.com/%0d%0aX-Test:1','https://example.com/\\bad']as$url){$bad=$payload;$bad['url']=$url;p13_reject(fn()=>$sponsors->saveEntry($entryId,$sponsors->snapshot()['revision'],$bad,false),'Unsafe destination rejected');}$before=$sponsors->snapshot();$bad=$payload;$bad['status']='enabled';$bad['ends_at']=gmdate('Y-m-d H:i:s',time()+3600);$bad['image_id']=PHP_INT_MAX;$bad['image_evidence']='No such attachment';p13_reject(fn()=>$sponsors->saveEntry($entryId,$before['revision'],$bad,true),'Missing raster attachment rejected');p13_assert($sponsors->snapshot()===$before,'Unsafe input leaves prior reviewed version intact');$bad=$payload;$bad['translations']['en_US']['title']='<script>alert(1)</script>';$clean=$sponsors->saveEntry($entryId,$before['revision'],$bad,false);$saved=end($clean['entries']);p13_assert(!str_contains(wp_json_encode($saved['translations']),'<script'),'Markup title is sanitized as plain text');$count=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('skills'));p13_assert($count>0,'Existing Skills still present');});
p13_case('sponsors_current_language_future_pause_and_expiry_without_cron',function()use($sponsors,$payload,$admin,&$entryId){wp_set_current_user($admin);$d=$payload;$d['status']='enabled';$d['starts_at']=gmdate('Y-m-d H:i:s',time()+3600);$d['ends_at']=gmdate('Y-m-d H:i:s',time()+7200);$s=$sponsors->saveEntry($entryId,$sponsors->snapshot()['revision'],$d,true);p13_assert($sponsors->publicEntry($entryId,'en_US')===null,'Future sponsorship excluded before its start');$d['status']='paused';$s=$sponsors->saveEntry($entryId,$s['revision'],$d,false);p13_assert($sponsors->publicEntry($entryId,'en_US')===null,'Pause suppresses immediately');$d['status']='enabled';$d['starts_at']=gmdate('Y-m-d H:i:s',time()-30);$d['ends_at']=gmdate('Y-m-d H:i:s',time()+3);$d['translations']['zh_CN']=['title'=>'','description'=>''];$s=$sponsors->saveEntry($entryId,$s['revision'],$d,true);p13_assert($sponsors->publicEntry($entryId,'en_US')!==null,'Live actual period displays');p13_assert($sponsors->publicEntry($entryId,'zh_CN')===null,'Missing translation never borrows English');sleep(4);p13_assert($sponsors->publicEntry($entryId,'en_US')===null,'Actual UTC expiry suppresses without Cron');p13_assert(Sponsors::displayState($s['entries'][array_key_last($s['entries'])])==='expired','Expired is derived state');});
p13_case('sponsors_skill_gate_keeps_publication_and_review_unchanged',function()use($sponsors,$payload,$admin,$management){$skill=p13_skill('sponsored');$draft=p13_skill('sponsor-draft',false);wp_set_current_user($admin);$d=$payload;$d['url']='';$d['skill_id']=$draft;$d['status']='enabled';$d['ends_at']=gmdate('Y-m-d H:i:s',time()+3600);p13_reject(fn()=>$sponsors->saveEntry(0,$sponsors->snapshot()['revision'],$d,true),'Draft cannot buy exposure');$d['skill_id']=$skill;$finger=p13_skill_fingerprint($skill);$s=$sponsors->saveEntry(0,$sponsors->snapshot()['revision'],$d,true);$id=$s['entries'][array_key_last($s['entries'])]['id'];$r=$sponsors->publicEntry($id,'zh_CN');p13_assert($r!==null&&$r['skill_id']===$skill,'Current verified bilingual Skill linked');p13_assert(p13_skill_fingerprint($skill)===$finger,'Sponsorship does not edit Skill content, review or versions');$management->archiveSkill($skill,p13_skill_revision($skill));p13_assert($sponsors->publicEntry($id,'en_US')===null&&$sponsors->publicEntry($id,'zh_CN')===null,'Withdrawal suppresses both languages immediately');});
wp_set_current_user($admin);$sponsors->setEnabled(false,$sponsors->snapshot()['revision']);
p13_report('Real WordPress/MySQL manual sponsor configuration, native capabilities, optimistic revisions, current publication/language gates and UTC expiry; synthetic local entries, no external requests.');
